  function speedingFineEur(country, excessKmh) {
    const over = Math.max(0, Math.round(excessKmh));
    if (country === "FR") {
      const amountEur2 = over >= 50 ? 1500 : over >= 40 ? 375 : 135;
      return { amountEur: amountEur2, label: `Radar automatique (+${over} km/h)` };
    }
    if (country === "DE") {
      const amountEur2 = over <= 10 ? 30 : over <= 15 ? 50 : over <= 20 ? 70 : over <= 25 ? 115 : over <= 30 ? 180 : over <= 40 ? 260 : over <= 50 ? 480 : over <= 60 ? 600 : 700;
      return { amountEur: amountEur2, label: `Blitzer (+${over} km/h)` };
    }
    const amountEur = over >= 40 ? 350 : over >= 20 ? 180 : 90;
    return { amountEur, label: `Radarkontrolle (+${over} km/h)` };
  }
  function buildSpeedTrapEvent(ctx) {
    const excess = Math.max(0, ctx.actualKmh - ctx.signKmh);
    const fine = speedingFineEur(ctx.country, excess);
    const brakeTo = Math.max(40, Math.round(ctx.signKmh / 5) * 5);
    const french = ctx.country === "FR";
    const driven = Math.round(ctx.actualKmh);
    return {
      id: "evt_speed_trap",
      title: french ? "Radar automatique / Gendarmerie" : ctx.country === "DE" ? "Blitzer am Fahrbahnrand" : "Radarkontrolle",
      category: "police",
      icon: "\u{1F4F8}",
      description: french ? `Ein Radar automatique hat dich erfasst. Du f\xE4hrst ${driven} km/h, erlaubt sind ${ctx.signKmh} km/h.` : `Blitzer. Du f\xE4hrst ${driven} km/h, das Schild sagt ${ctx.signKmh}.`,
      requiresSpeeding: true,
      choices: [
        {
          id: "brake_smooth",
          label: `Sofort vom Strom und sanft auf ${brakeTo} km/h rekuperieren`,
          hint: "Kein Bu\xDFgeld \xB7 +3 Min \xB7 +8 Dynamik-Punkte",
          timeDeltaMin: 3,
          socDeltaPct: 1,
          costDeltaEur: 0,
          stressDelta: 4,
          decisionPoints: 10,
          adjustSpeedKmh: brakeTo,
          resultText: "Rechtzeitig abgebremst \u2013 kein Blitz."
        },
        {
          id: "risk_ticket",
          label: french ? "Weiterfahren \u2013 vielleicht ist das Radar aus" : "Laufen lassen \u2013 vielleicht ist der Blitzer aus",
          hint: `65 % Risiko auf ${fine.amountEur} \u20AC \xB7 0 Min`,
          timeDeltaMin: 0,
          socDeltaPct: 0,
          costDeltaEur: 0,
          stressDelta: 11,
          decisionPoints: -8,
          fineRisk: { probability: 0.65, amountEur: fine.amountEur, label: fine.label },
          resultText: french ? "Du l\xE4sst das Tempo stehen\u2026" : "Du h\xE4ltst das Tempo\u2026"
        }
      ]
    };
  }
  function buildTailgateEvent(country, amountEur) {
    const where = country === "FR" ? "Frankreich (Abstand / N\xF6tigung)" : country === "DE" ? "Deutschland (Abstandsversto\xDF)" : "Benelux";
    const base = GAME_EVENTS.evt_tailgate;
    const choice = base.choices[0];
    return {
      ...base,
      description: `Zu dicht aufgefahren, links geblinkt und die Lichthupe gegeben. Kontrolle in ${where}.`,
      choices: [
        {
          ...choice,
          hint: `+${amountEur} \u20AC \xB7 +8 Min \xB7 +10 Stress`,
          fineDeltaEur: amountEur,
          resultText: `Kontrolle (${where}): ${amountEur} \u20AC wegen zu geringem Abstand.`
        }
      ]
    };
  }
  function getEventById(id) {
    return GAME_EVENTS[id];
  }
  function getWifeDialogueById(id) {
    return WIFE_DIALOGUES[id];
  }

