  function speedSignHtml(limitKmh) {
    if (limitKmh <= 0) {
      const title2 = "Unbeschr\xE4nkt";
      return `<span class="speed-sign end" title="${title2}" aria-label="${title2}"></span>`;
    }
    const title = `Tempolimit ${limitKmh} km/h`;
    return `<span class="speed-sign" title="${title}" aria-label="${title}">${limitKmh}</span>`;
  }

